 const progress=global&&valid?`<p>已发现 ${discovered} 个本机来源；${checked} 个状态已核对；${discovered-checked} 个待确认。</p>${discovered?`<label class="observer-progress">状态核对进度<progress max="${discovered}" value="${checked}" aria-label="本机原生会话状态核对进度">${checked}/${discovered}</progress></label>`:''}`:`<p>${global?'正在核对本机原生会话状态。':'正在观察已配置的桌面项目。'}</p>`;
