function botDialog(id){const bot=state.bots.find(x=>x.id===id);openDialog(bot?'编辑机器人':'新增 QQ 机器人','登记资料后，可为机器人关联一个 Agent 实例。',field('机器人名称','entity-name','例如：开发助手')+field('AppID（选填）','app-id',bot?'留空保持已登记值':'填写 QQ 官方机器人 AppID',bot?'此处不会显示已保存的完整 AppID。':'只保存在本机，本轮不会建立 QQ 连接。'),async()=>{const name=$('#entity-name').value,appId=$('#app-id').value.trim(),data={name};if(appId||!bot)data.appId=appId;await mutate(bot?'/api/bots/'+bot.id:'/api/bots',bot?'PATCH':'POST',data);});if(bot)$('#entity-name').value=bot.name;$('#entity-name').required=true;$('#app-id').maxLength=30;$('#app-id').inputMode='numeric';$('#app-id').pattern='[0-9]*';}
function agentDialog(id,toolId){const agent=state.agents.find(x=>x.id===id);openDialog(agent?'编辑 Agent':'登记 Agent 实例','登记只保存实例配置，不会启动工具或调用模型。',field('实例名称','entity-name','例如：项目开发 Agent')+(agent?`<label class="field"><span>所属工具</span><input disabled value="${esc(state.tools.find(t=>t.id===agent.toolId)?.name||agent.toolId)}"></label>`:`<label class="field"><span>所属工具</span><select id="tool-id">${state.tools.map(t=>`<option value="${t.id}">${esc(t.name)} · 未接入模型</option>`).join('')}</select><small>这是实例所属的工具类型，实际接入将在后续阶段启用。</small></label>`),async()=>{const data={name:$('#entity-name').value};if(!agent)data.toolId=$('#tool-id').value;await mutate(agent?'/api/agents/'+agent.id:'/api/agents',agent?'PATCH':'POST',data);});if(agent)$('#entity-name').value=agent.name;else if(toolId)$('#tool-id').value=toolId;$('#entity-name').required=true;}
function bindingDialog(id){const bot=state.bots.find(x=>x.id===id),bound=state.bindings.find(x=>x.botId===id);const choices=state.agents.filter(a=>a.status!=='paused'&&!state.bindings.some(b=>b.agentId===a.id&&b.botId!==id));openDialog('关联 Agent',`为「${bot.name}」指定对应的 Agent 实例。`,`<label class="field"><span>对应 Agent</span><select id="bind-agent"><option value="">不关联 Agent</option>${choices.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(state.tools.find(t=>t.id===a.toolId)?.name||a.toolId)}</option>`).join('')}</select><small>${choices.length?'每个 Agent 实例只对应一个机器人。':'还没有可绑定的实例。请先在 Agent 实例页登记。'}</small></label>`,async()=>{await mutate('/api/bindings','PUT',{botId:id,agentId:$('#bind-agent').value||null});});if(bound&&choices.some(a=>a.id===bound.agentId))$('#bind-agent').value=bound.agentId;}
function archiveDialog(kind,id){const entity=state[kind].find(x=>x.id===id);openDialog('归档'+(kind==='bots'?'机器人':' Agent'),`将「${entity.name}」从当前列表移出。`,`<div class="dialog-copy"><p>登记历史会保留在本机。${kind==='bots'?'对应绑定会解除，Agent 实例仍然保留。':'如果仍有关联机器人，请先解除绑定。'}</p></div>`,async()=>{await mutate('/api/'+kind+'/'+id,'DELETE',{});},'确认归档');}
document.addEventListener('click',async event=>{
 const nav=event.target.closest('[data-nav]');if(nav){event.preventDefault();navigate(nav.dataset.nav);return;}
 const el=event.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;
 try{
  if(action==='close-dialog'){$('#editor-dialog').close();return;}
  if(action==='connection-provider'){if(connectionProviders.some(p=>p.id===id)){connectionProvider=id;navigate('connections');}return;}
  if(action==='diagnostics-preview'){
   const result=await api('/api/diagnostics/preview');openDialog('脱敏诊断预览','只在本机保存以下内容；不会上传。',`<pre class="approval-details">${esc(JSON.stringify(result.preview,null,2))}</pre><p>导出保存到当前数据目录的 diagnostics 子目录。账号资料、凭据、消息正文、记忆、原始日志和真实路径均不包含在内。</p>`,async()=>{await api('/api/diagnostics/export',{method:'POST',body:JSON.stringify({operationId:crypto.randomUUID(),expectedRevision:state.revision,expectedSetupRevision:result.preview.setup.revision,previewSha256:result.sha256})});},'保存脱敏诊断');return;
  }
  if(action.startsWith('setup-')){
   el.disabled=true;const kind=action.slice(6);
   if(kind==='status')await load();
   else if(kind==='consent')setupConsentDialog();
   else if(kind==='project')setupProjectDialog();
   else if(kind==='verification-project')openDialog('建立连接验证目录','仅创建新的合成目录并授权其中的读写与命令工具。','<p>验证目录放在本机文档下的 QQAgentWorkspaces 实例子目录。可以先用它测试接入，再单独授权实际项目。</p>',async()=>{await setupRequest(kind);},'建立并授权');
   else if(kind==='self-test')openDialog('运行一次 Codex 自检','使用当前账号和所选模型验证本机执行边界。','<p>先核对项目可读写、私有目录隔离、环境变量与网络限制，再在全新合成目录调用一次模型。未知结果会保留，不能直接重新执行。</p>',async()=>{await setupRequest(kind);},'开始一次自检');
   else if(kind==='pair-code')await showPairCode(id);
   else if(kind==='pair'){const operationId=crypto.randomUUID();await setupRequest(kind,{operationId});await showPairCode(operationId);}
   else if(kind==='initialize'||kind==='activate'){await setupRequest(kind);toast(kind==='initialize'?'已开始创建本机业务数据。':'已请求启用，请核对机器人连接状态。');}
   return;
  }
  if(action.startsWith('business-')){
   el.disabled=true;
   if(action==='business-status')await load();
   else if(action==='business-project')businessProjectDialog();
   else if(action==='business-prepare'){await businessRequest('prepare',{operationId:crypto.randomUUID()});toast('已开始保留原资料，请刷新核对结果。');}
   else if(action==='business-start'){if(!canStartExistingBusiness())throw Error('当前实例未满足恢复启动条件，请先在本机初始化中核对配对、配置和执行验证。');await businessRequest('start',{operationId:crypto.randomUUID()});toast('已请求启动机器人，请刷新连接状态。');}
   else if(action==='business-stop'){await businessRequest('stop',{operationId:crypto.randomUUID(),instance:state.business.instance});toast('已请求停止，正在保存当前状态。');}
   else if(action==='business-approve'){
    const p=state.business.pendingApprovals.find(x=>x.id===id);if(!p)throw Error('审批已变化，请刷新。');
    openDialog('本机任务审批','逐项核对操作与项目范围。',`<pre class="approval-details">${esc(p.details)}</pre><label class="field"><span>本次决定</span><select id="business-decision"><option value="decline">拒绝此操作</option>${p.canAccept?'<option value="accept">允许当前项目授权范围内的操作</option>':''}</select></label>${!p.canAccept?'<p>此请求未证明受当前项目约束，可拒绝后重新调整本机项目授权。</p>':''}`,async()=>{await businessRequest('approve',{operationId:crypto.randomUUID(),instance:state.business.instance,id:p.id,fingerprint:p.fingerprint,accept:$('#business-decision').value==='accept'});},'提交本次决定');
   }
   return;
  }
  if(action.startsWith('qq-')){
   const bot=state.bots.find(b=>state.bindings.some(x=>x.botId===b.id&&x.agentId===state.codexAccount?.agentId));el.disabled=true;
   if(action==='qq-status')await qqRequest('status');
   else if(action==='qq-credentials'&&bot)qqCredentialDialog(bot);
   else if(action==='qq-verify'&&bot){const operationId=crypto.randomUUID();pendingQQVerificationId=operationId;state.qqConnection={...state.qqConnection,state:'verifying',verification:{operationId,state:'intent',canCancel:true}};render();try{await qqRequest('verify',{botId:bot.id,operationId});}finally{if(pendingQQVerificationId===operationId)pendingQQVerificationId=null;}}
   else if(action==='qq-cancel'&&bot){const target=pendingQQVerificationId||state.qqConnection.verification?.operationId;state.qqConnection=await api('/api/qq/connection');if(state.qqConnection.verification?.operationId===target&&state.qqConnection.verification.canCancel)await qqRequest('cancel',{botId:bot.id,operationId:crypto.randomUUID(),verificationOperationId:target});else{render();toast('原核验状态已变化，请核对当前结果。');}}
   else if(action==='qq-disconnect'&&bot)await qqRequest('disconnect',{botId:bot.id,operationId:crypto.randomUUID()});
   return;
  }
  if(action.startsWith('account-')){
   el.disabled=true;
   if(action==='account-associate')await accountRequest('associate',{agentId:$('#account-agent').value});
   else if(action==='account-status')await accountRequest('status');
   else if(action==='account-login'){await accountRequest('login',{operationId:crypto.randomUUID(),type:el.dataset.type});if(state.codexAccount.login?.handoffAvailable)await showAccountHandoff();}
   else if(action==='account-handoff')await showAccountHandoff();
   else if(action==='account-cancel')await accountRequest('cancel',{operationId:crypto.randomUUID(),loginOperationId:state.codexAccount.login.operationId});
   else if(action==='account-model')await accountRequest('model',{model:$('#account-model').value});
   else if(action==='account-logout'||action==='account-close')openDialog(action==='account-logout'?'退出本插件账号':'结束本插件连接',action==='account-logout'?'退出后需要重新登录和选择模型。':'结束本插件自有账号进程，未确认的登录结果会保留为未知。','<div class="dialog-copy"><p>此操作仅作用于当前插件的独立账号目录。</p></div>',async()=>{await accountRequest(action==='account-logout'?'logout':'close',{operationId:crypto.randomUUID()});},'确认操作');
   return;
  }
  if(action==='add-bot'||action==='edit-bot')botDialog(id);
  else if(action==='add-agent'||action==='edit-agent')agentDialog(id);
  else if(action==='bind')bindingDialog(id);
  else if(action==='archive-bot')archiveDialog('bots',id);
  else if(action==='archive-agent')archiveDialog('agents',id);
  else if(action==='toggle-bot'||action==='toggle-agent'){const kind=action==='toggle-bot'?'bots':'agents',entity=state[kind].find(x=>x.id===id);el.disabled=true;await mutate('/api/'+kind+'/'+id,'PATCH',{status:entity.status==='paused'?'registered':'paused'});toast('配置状态已更新');}
  else if(action==='tool-agents'){view='agents';query='';statusFilter='all';toolFilter=id;history.replaceState(null,'','#agents');render();}
  else if(action==='help')openDialog('从这里开始','所有配置都由这一个本机网关管理。','<div class="dialog-copy"><p><strong>1. 核对 Codex 接入</strong><br>在「接入 → Codex」查看账号与真实执行验证。</p><p><strong>2. 使用原机器人</strong><br>原聊天、人设、记忆和任务记录保留在本机。机器人只回应原已配对用户。</p><p><strong>3. 授权工作项目</strong><br>停止机器人后添加明确的项目文件夹，再启动服务。通过 QQ 发送「菜单」选择聊天或工作。</p><p>DSH 与 Gemini 接入已暂缓。</p></div>',null);
  else if(action==='settings')settingsDialog();
 }catch(e){toast(e.message);if(['account-','qq-','business-','setup-'].some(prefix=>action.startsWith(prefix))){try{await load();}catch{}}}finally{if(el.isConnected)el.disabled=false;}
});
$('#editor-dialog').addEventListener('close',()=>{$('#dialog-fields').replaceChildren();submitHandler=null;});
$('#editor-form').addEventListener('submit',async event=>{event.preventDefault();if(!submitHandler)return;const revision=state.revision;const button=$('#dialog-submit');button.disabled=true;$('#form-error').textContent='';try{await submitHandler();$('#editor-dialog').close();toast('本机配置已保存');}catch(e){$('#form-error').textContent=e.message;try{await load();}catch{}if(revision!==state.revision)$('#form-error').textContent+=' 列表已刷新，请核对当前内容。';}finally{button.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='list-search'){query=event.target.value;$('#list-rows').innerHTML=view==='agents'?agentRows():botRows();}});
document.addEventListener('change',event=>{if(event.target.id==='status-filter'){statusFilter=event.target.value;$('#list-rows').innerHTML=view==='agents'?agentRows():botRows();}});
(async()=>{try{const bootstrap=await api('/api/bootstrap');csrf=bootstrap.csrf;view=location.hash.slice(1)==='account'?'connections':titles[location.hash.slice(1)]?location.hash.slice(1):'overview';await load();}catch(e){$('#service-dot').classList.add('offline');$('#service-text').textContent='管理服务未连接';$('#main').innerHTML=`<div class="error-panel">${esc(e.message)}<br>请通过「打开管理界面.cmd」启动服务后刷新页面。</div>`;}})();
let statusPollInFlight=false;
const connectionDisplayState=()=>JSON.stringify([state.tools,state.codexAccount,state.qqConnection,state.business,state.setup,state.codexWork]);
function refreshStatusView(){if(statusRenderPending&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){render();statusRenderPending=false;}}
setInterval(async()=>{
 if($('#editor-dialog').open||statusPollInFlight)return;
 statusPollInFlight=true;
 try{
  const revision=state.revision,before=connectionDisplayState(),wasFresh=connectionStateFresh;await load(false);
  if(state.revision!==revision||before!==connectionDisplayState()||!wasFresh)statusRenderPending=true;
  refreshStatusView();
 }catch{connectionStateFresh=false;statusRenderPending=true;$('#service-dot').classList.add('offline');$('#service-text').textContent='管理服务连接中断';refreshStatusView();}finally{statusPollInFlight=false;}
},5000);
